import yaml

with open('docker-compose.yml') as f:
    raw = f.read()
data = yaml.safe_load(raw)

assert 'hunter2' not in raw, "hardcoded secret 'hunter2' is still present in docker-compose.yml"

services = data.get('services') or {}
assert 'app' in services, f'app service missing, got {list(services)}'
app = services['app']

def env_to_dict(env):
    if env is None:
        return {}
    if isinstance(env, dict):
        return {str(k): str(v) for k, v in env.items()}
    out = {}
    for item in env:
        item = str(item)
        if '=' in item:
            k, v = item.split('=', 1)
            out[k] = v
        else:
            out[item] = ''
    return out

app_env = env_to_dict(app.get('environment'))
has_env_file = bool(app.get('env_file'))
has_secrets = bool(app.get('secrets'))

db_pw_key = next((k for k in app_env if k.upper() == 'DB_PASSWORD'), None)
if db_pw_key is not None:
    value = app_env[db_pw_key].strip()
    assert value.startswith('${') or has_env_file, (
        f'DB_PASSWORD should reference an environment variable (e.g. ${{DB_PASSWORD}}) rather than '
        f'a literal, got {value!r}'
    )
else:
    assert has_env_file or has_secrets, (
        'DB_PASSWORD was removed from environment but no env_file/secrets mechanism replaces it'
    )

# unrelated config must survive
assert app.get('image') == 'myorg/webapp:latest', f'app image changed unexpectedly: {app.get("image")!r}'

print('PASS')
